UPDATE draw_request
SET status = 1,
    result_payload = #{resultPayload},
    completed_time = #{completedTime},
    updated_time = #{completedTime}
WHERE request_id = #{requestId}
  AND status = 0
  AND execution_token = #{executionToken}

UPDATE draw_request
SET status = 2,
    completed_time = #{completedTime},
    updated_time = #{completedTime}
WHERE request_id = #{requestId}
  AND status = 0
  AND execution_token = #{executionToken}
